 useEffect(()=>{let mounted=true; const initialize=async()=>{if(hasEmbeddedCurriculum){return;} setCurriculumLoad({status:'loading',loaded:0,total:EXPECTED_LISTS}); try{const cached=await readCurriculumCache();if(cached){if(mounted){setCurriculumData(cached);setCurriculumLoad({status:'cached',loaded:EXPECTED_LISTS,total:EXPECTED_LISTS});}return;} const imported=await loadCurriculum((loaded,total,label)=>{if(mounted)setCurriculumLoad({status:'loading',loaded,total,message:label});});if(mounted){setCurriculumData(imported);setCurriculumLoad({status:'ready',loaded:EXPECTED_LISTS,total:EXPECTED_LISTS});}}catch(error){if(mounted){setCurriculumLoad({status:'error',loaded:0,total:EXPECTED_LISTS,message:error instanceof Error?error.message:'The curriculum could not be loaded.'});}}}; void initialize();return()=>{mounted=false};},[curriculumAttempt,hasEmbeddedCurriculum]);
 const t=(key:string)=>uiText[ui]?.[key]||uiText.en[key]||key;
 useEffect(()=>{document.documentElement.dataset.theme=theme;storageSet('yukoto-theme',theme)},[theme]); useEffect(()=>{storageSet('yukoto-study',study)},[study]);useEffect(()=>{storageSet('yukoto-ui',ui)},[ui]);useEffect(()=>{storageSet('yukoto-completed',JSON.stringify(completed))},[completed]); useEffect(()=>{setQuizIndex(0);setChoice('');setChecked(false);setQuizDone(false);},[curriculumData.entries.length,curriculumScheme,curriculumLevel]);
 const go=(p:Page)=>{setPage(p);setMobileNav(false);window.scrollTo({top:0,behavior:'smooth'})};
 const playToneRecording=(url:string)=>{window.speechSynthesis?.cancel();const audio=toneAudioRef.current||new Audio();toneAudioRef.current=audio;audio.pause();audio.src=url;audio.currentTime=0;setToneAudioError(false);void audio.play().catch(()=>setToneAudioError(true))};
