 const markComplete=(id:string)=>setCompleted(prev=>prev.includes(id)?prev:[...prev,id]);
 const speechCurriculumPool=useMemo(()=>curriculumData.entries.filter(entry=>entry.levels.some(tag=>{const [scheme,number]=tag.split('-');return scheme===curriculumScheme&&Number(number)<=curriculumLevel})),[curriculumData.entries,curriculumScheme,curriculumLevel]); const speechCurriculumEntry=speechCurriculumPool.length?speechCurriculumPool[speechPracticeIndex%speechCurriculumPool.length]:null; const quizItems=useMemo(()=>{const fallback=[{q:'What does 谢谢 mean?',options:['Hello','Thank you','Goodbye'],answer:'Thank you',hanzi:'谢谢',pinyin:'xièxie'},{q:'Which phrase means “Please help me”?',options:['请帮我','我喜欢茶','再见'],answer:'请帮我',hanzi:'请帮我',pinyin:'qǐng bāng wǒ'},{q:'What does 我不懂 mean?',options:["I understand",'I do not understand','I am tired'],answer:'I do not understand',hanzi:'我不懂',pinyin:'wǒ bù dǒng'}]; const pool=curriculumData.entries.filter(entry=>entry.meanings.length>0&&entry.levels.some(tag=>{const [scheme,number]=tag.split('-');return scheme===curriculumScheme&&Number(number)<=curriculumLevel})); if(pool.length<3)return fallback; const shuffled=[...pool];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}return shuffled.slice(0,10).map(entry=>{const answer=getEntryMeanings(entry,curriculumScheme,curriculumLevel)[0]||entry.meanings[0];const distractors=shuffled.filter(other=>other.id!==entry.id&&(getEntryMeanings(other,curriculumScheme,curriculumLevel)[0]||other.meanings[0])&&(getEntryMeanings(other,curriculumScheme,curriculumLevel)[0]||other.meanings[0])!==answer).slice(0,18).map(other=>getEntryMeanings(other,curriculumScheme,curriculumLevel)[0]||other.meanings[0]);const options=[...new Set([answer,...distractors])].slice(0,3);while(options.length<3)options.push(['A different meaning','Not this meaning','Another word'][options.length]);for(let i=options.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[options[i],options[j]]=[options[j],options[i]];}return{q:'Choose the closest meaning.',options,answer,hanzi:entry.hanzi,pinyin:getEntryPinyin(entry,curriculumScheme,curriculumLevel),id:entry.id};});},[curriculumData.entries,curriculumScheme,curriculumLevel]);
 const pinyinQuestions=[{q:'Which tone does mā use?',options:['First — high and level','Second — rising','Fourth — falling'],answer:'First — high and level'},{q:'What is the tone pattern in nǐ hǎo?',options:['First + first','Third + third (often sounds 2nd + 3rd)','Fourth + fourth'],answer:'Third + third (often sounds 2nd + 3rd)'},{q:'What is Pinyin for?',options:['Replacing Chinese characters forever','Showing Mandarin pronunciation','Showing word order only'],answer:'Showing Mandarin pronunciation'}];
